custom_fields.inner:
[[[
const d = variables.dl, t = d.t, L = t.labels, e = d.esc;
const now = new Date();
const DAYS = ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'], MON = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
const dt = DAYS[now.getDay()] + ' · ' + MON[now.getMonth()] + ' ' + now.getDate();
const sub = e(variables.sub || '').replace('@DATE@', dt);
let c;
if (!d.alert || !d.text) {
  c = "<div class='cond'><div class='lbl'>" + e(L.status) + "</div><div class='st'>" + e(L.normal) + "</div></div>";
} else if (d.hot) {
  c = "<div class='cond'><span class='abox'>" + e(L.alert) + "</span><div class='why'>" + d.reason + "</div></div>";
} else {
  c = "<div class='cond'><div class='lbl'>" + e(L.status) + "</div><div class='st al'>" + e(L.alert) + "</div><div class='why'>" + d.reason + "</div></div>";
}
const bt = [d.auto, t.badge].filter((x) => x).join(' · ');      // e.g. "Holidays · October · Peak Color"
const badge = bt ? "<div class='bdg'>" + e(bt) + "</div>" : '';
return "<div class='in " + t.shape.header + (d.hot ? ' hot' : '') + "'><div>" + badge + "<div class='t1'>" + e(variables.title || '') + "</div><div class='t2'>" + sub + "</div></div>" + c + "</div>";
]]]

