.in{position:relative;display:flex;gap:16px;align-items:flex-end;justify-content:space-between;flex-wrap:wrap;
    padding:26px 22px 18px;box-sizing:border-box;min-height:132px;
    background-image:var(--dl-pat);background-size:120px 120px;background-repeat:repeat}
.in::before{content:"";position:absolute;background:var(--dl-g2)}
.in.rail{padding-left:36px}
.in.rail::before{left:0;top:0;bottom:0;width:14px}
.in.band{padding-top:36px}
.in.band::before{left:0;right:0;top:0;height:10px}
.in.hot::before{background:var(--dl-acc);animation:var(--dl-pulse)}
.in.plain{padding-left:22px}
.in.plain::before{display:none}
.in.plain.hot::before{display:block;left:0;top:0;bottom:0;width:6px}
.bdg{display:inline-block;font-size:var(--fs-code);letter-spacing:calc(2px * var(--dl-ls, 1));color:var(--dl-txt2);margin-bottom:6px;text-transform:var(--dl-case, uppercase)}
.t1{font-size:var(--fs-title);font-weight:700;letter-spacing:calc(2px * var(--dl-ls, 1));line-height:1.05;color:var(--dl-g1);text-transform:var(--dl-case, uppercase)}
.t2{font-size:var(--fs-sub);letter-spacing:calc(1.5px * var(--dl-ls, 1));color:var(--dl-data);margin-top:8px;text-transform:var(--dl-case, uppercase)}
.cond{display:flex;flex-direction:column;align-items:flex-end;gap:6px;text-align:right;margin-left:auto}
.cond .lbl{font-size:var(--fs-code);letter-spacing:calc(2px * var(--dl-ls, 1));color:var(--dl-txt2);text-transform:var(--dl-case, uppercase)}
.cond .st{font-size:var(--fs-cond);font-weight:700;letter-spacing:calc(2px * var(--dl-ls, 1));line-height:1;color:var(--dl-data);text-transform:var(--dl-case, uppercase)}
.cond .st.al{color:var(--dl-acc)}
.abox{white-space:var(--dl-wrap, nowrap);border:3px solid var(--dl-acc);border-radius:var(--dl-r);padding:4px 16px;font-size:var(--fs-cond);
      font-weight:700;letter-spacing:calc(3px * var(--dl-ls, 1));color:var(--dl-txt);background:var(--dl-track);animation:var(--dl-pulse);text-transform:var(--dl-case, uppercase)}
.why{font-size:var(--fs-label);letter-spacing:calc(1.5px * var(--dl-ls, 1));color:var(--dl-g1);text-transform:var(--dl-case, uppercase);max-width:42ch}
@media (max-width:700px){
  .in{flex-direction:column;align-items:flex-start;gap:10px;padding:18px 16px 14px;min-height:0}
  .in.rail{padding-left:26px}
  .in.rail::before{width:10px}
  .in.band{padding-top:26px}
  .cond{align-items:flex-start;text-align:left;margin-left:0}
  .abox{letter-spacing:2px}
}

