const d = variables.dl, e = d.esc, s = entity;
if (!s) return "<div class='cp warn'><i class='sd'></i><div class='tx'><small>" + e(variables.name || 'Missing entity') + "</small><b>Not found</b></div></div>";
const a = s.attributes || {}, st = String(s.state), dom = s.entity_id.split('.')[0];
const na = ['unavailable', 'unknown'].includes(st);
const on = ["on", "open", "heat", "cool", "heat_cool", "auto", "dry", "fan_only", "playing", "home", "unlocked", "active"].includes(st);
const nm = variables.name || a.friendly_name || s.entity_id;
let val;
if (variables.value !== undefined && variables.value !== null && variables.value !== '') val = String(variables.value);
else if (na) val = st === 'unknown' ? 'Unknown' : 'Offline';
else if (hass && typeof hass.formatEntityState === 'function') val = hass.formatEntityState(s);
else {
  const n = Number(st);
  val = (st.trim() !== '' && !isNaN(n)) ? n.toFixed(variables.d === undefined ? 1 : variables.d) + (a.unit_of_measurement ? ' ' + a.unit_of_measurement : '')
      : st.charAt(0).toUpperCase() + st.slice(1).replace(/_/g, ' ');
}
const tone = variables.tone || (na ? 'warn' : (on ? 'ok' : ''));
let p = null;
if (variables.bar === false) p = null;
else if (typeof variables.bar === 'number') p = variables.bar;
else if (dom === 'light') p = st === 'on' ? (a.brightness ? a.brightness / 2.55 : 100) : 0;
else if (dom === 'fan' && a.percentage !== undefined && a.percentage !== null) p = st === 'on' ? a.percentage : 0;
else if (dom === 'cover' && a.current_position !== undefined) p = a.current_position;
else if ((dom === 'input_number' || dom === 'number') && a.max > a.min && !na) p = (Number(st) - a.min) / (a.max - a.min) * 100;
let ago = '';
if (variables.ago !== false && s.last_changed) {
  const m = Math.max(0, Math.round((Date.now() - Date.parse(s.last_changed)) / 60000));
  ago = m < 1 ? 'just now' : (m < 60 ? m + ' min ago' : (m < 1410 ? Math.round(m / 60) + ' hr ago' : (m < 2160 ? '1 day ago' : Math.round(m / 1440) + ' days ago')));
}
const bar = p === null ? '' : "<div class='br'><span style='width:" + Math.max(0, Math.min(100, p)).toFixed(0) + "%'></span></div>";
return "<div class='cp " + e(tone) + (variables.big ? ' big' : '') + "'><i class='sd'></i><div class='tx'><small>" + e(nm) + "</small><b>" + e(val) + "</b>"
  + (ago ? "<em>" + ago + "</em>" : '') + "</div>" + bar + "</div>";
]]]

