[[[
const d = variables.dl, e = d.esc;
const list = Array.isArray(variables.chips) ? variables.chips : [];
const fmt = (c) => {
  if (c.v !== undefined && c.v !== null) return [String(c.v), null];
  const s = c.e ? states[c.e] : null;
  if (!s) return ['--', 'na'];
  const raw = c.a ? (s.attributes ? s.attributes[c.a] : undefined) : s.state;
  if (raw === undefined || raw === null || ['unavailable', 'unknown'].includes(String(raw))) return ['Offline', 'na'];
  const n = Number(raw), u = c.u !== undefined ? c.u : ((!c.a && s.attributes && s.attributes.unit_of_measurement) || '');
  if (String(raw).trim() !== '' && !isNaN(n) && typeof raw !== 'boolean') return [n.toFixed(c.d === undefined ? 1 : c.d) + (u ? ' ' + u : ''), String(raw)];
  const t = String(raw);
  const map = c.map && c.map[t] !== undefined ? c.map[t] : null;
  return [map !== null ? map : t.charAt(0).toUpperCase() + t.slice(1).replace(/_/g, ' '), t];
};
const tone = (c, raw) => {
  if (c.tone) return c.tone;
  if (raw === 'na') return 'warn';
  const r = String(raw || '').toLowerCase();
  if ((c.hot || []).includes(r)) return 'hot';
  if ((c.warn || []).includes(r)) return 'warn';
  if ((c.ok || []).includes(r)) return 'ok';
  return '';
};
const out = list.filter((c) => c).map((c) => {
  const f = fmt(c), g = d.go(c.go);
  return "<div class='sc " + e(tone(c, f[1])) + "'" + g + "><i></i><div><small>" + e(c.n || '') + "</small><b>" + e(f[0]) + "</b></div>" + (g ? "<u>›</u>" : '') + "</div>";
});
return "<div class='sg' style='--sg-min:" + (Number(variables.min) || 170) + "px'>" + out.join('') + "</div>";
]]]

