[[[
const d = variables.dl, e = d.esc, s = entity;
if (!s) return "<div class='dst hot'><small>Dial</small><b>Thermostat not found</b></div>";
const a = s.attributes || {};
const C = !!(hass && hass.config && hass.config.unit_system && hass.config.unit_system.temperature === '°C');
const unit = variables.unit || (C ? '°C' : '°F');
let lo = Number(variables.min !== undefined ? variables.min : (C ? 10 : 50));
let hi = Number(variables.max !== undefined ? variables.max : (C ? 32 : 90));
if (!(hi > lo)) { lo = C ? 10 : 50; hi = C ? 32 : 90; }          // bad range in the card config: use the default
const num = (v) => (v === null || v === undefined || v === '' || isNaN(Number(v))) ? null : Number(v);
const cs = variables.current ? states[variables.current] : null;
const cur = cs ? num(cs.state) : num(a.current_temperature);
const tgt = num(a.temperature), tl = num(a.target_temp_low), th = num(a.target_temp_high);
