dl_dial.extra_styles:
ha-card{
  --fs-code:max(calc(12.5px * var(--dl-scale)), var(--dl-min, 0px)); --fs-label:max(calc(17px * var(--dl-scale)), var(--dl-min, 0px)); --fs-val:max(calc(19.5px * var(--dl-scale)), var(--dl-min, 0px));
