  ha-card{
    --fs-code:max(calc(11.5px * var(--dl-scale)), var(--dl-min, 0px)); --fs-label:max(calc(14.5px * var(--dl-scale)), var(--dl-min, 0px)); --fs-val:max(calc(17px * var(--dl-scale)), var(--dl-min, 0px));
