.pt .nm{font-size:var(--fs-ptitle);font-weight:700;letter-spacing:calc(1.5px * var(--dl-ls, 1));color:var(--dl-g1);text-transform:var(--dl-case, uppercase);white-space:var(--dl-wrap, nowrap);overflow:hidden;text-overflow:var(--dl-cut, ellipsis)}
.pt .ln{flex:1;min-width:12px}
.pt .cd{font-size:var(--fs-code);letter-spacing:calc(1px * var(--dl-ls, 1));color:var(--dl-txt2);white-space:var(--dl-wrap, nowrap);min-width:0;overflow:hidden;text-overflow:var(--dl-cut, ellipsis);flex:0 1 auto}
.pt .nm{min-width:0;flex:0 1 auto}
