.pt.tab .ln{height:4px;background:var(--dl-g3);border-radius:2px}
.pt.underline{border-bottom:2px solid var(--dl-g3);box-shadow:inset 0 -2px 0 0 transparent;position:relative}
.pt.underline::after{content:"";position:absolute;left:14px;bottom:-2px;width:48px;height:2px;background:var(--dl-g2)}
