.dial{display:grid;grid-template-columns:minmax(0,1.1fr) minmax(0,1fr);gap:18px;align-items:center}
.dial.solo{grid-template-columns:minmax(0,1fr)}
.gauge{width:100%;max-width:330px;aspect-ratio:1/1;position:relative;container-type:inline-size;justify-self:center}
.gauge svg{width:100%;height:100%;display:block}
