.gauge text.tk{font-size:max(20px, calc(var(--dl-min, 0px) * 1.24))}.gauge text.rg{font-size:max(17px, calc(var(--dl-min, 0px) * 1.24))}
@container (max-width:299.9px){.gauge text.tk{font-size:max(20px, calc(var(--dl-min, 0px) * 1.49))}.gauge text.rg{font-size:max(17px, calc(var(--dl-min, 0px) * 1.49))}}
@container (max-width:249.9px){.gauge text.tk{font-size:max(20px, calc(var(--dl-min, 0px) * 1.86))}.gauge text.rg{font-size:max(17px, calc(var(--dl-min, 0px) * 1.86))}}
@container (max-width:199.9px){.gauge text.tk{font-size:max(20px, calc(var(--dl-min, 0px) * 2.48))}.gauge text.rg{font-size:max(17px, calc(var(--dl-min, 0px) * 2.48))}}
