.ctr .hero{font-size:18cqi;font-weight:600;line-height:.95;color:var(--dl-txt);white-space:nowrap}
.ctr .hero sup{font-size:max(.4em, var(--dl-min, 0px));vertical-align:top;position:relative;top:.25em;color:var(--dl-txt2)}
.ctr .sub{font-size:max(5.4cqi, var(--dl-min, 0px));color:var(--dl-data);letter-spacing:.1cqi;white-space:var(--dl-wrap, nowrap);max-width:var(--dl-ctrw, none);text-align:center}
.reads{display:flex;flex-direction:column;gap:14px;min-width:0}
.rd{display:grid;grid-template-columns:6px minmax(0,1fr);gap:12px}
.rd i{background:var(--dl-g2);border-radius:3px}.rd.ok i{background:var(--dl-data)}.rd.hot i{background:var(--dl-acc)}.rd.warn i{background:var(--dl-amber)}
.rd small{display:block;font-size:var(--fs-label);letter-spacing:calc(1.5px * var(--dl-ls, 1));color:var(--dl-txt2);text-transform:var(--dl-case, uppercase)}
.rd b{display:block;font-size:var(--fs-metric);font-weight:600;line-height:1.05}
.rd.hot b{color:var(--dl-acc)}.rd.ok b{color:var(--dl-data)}
.rd span{display:block;font-size:var(--fs-label);color:var(--dl-txt2);letter-spacing:.8px;line-height:1.25}
.dst{margin-top:12px;border-left:6px solid var(--dl-g2);padding-left:12px;text-align:left}
.dst.hot{border-left-color:var(--dl-acc)}
.dst small{font-size:var(--fs-code);letter-spacing:calc(1.5px * var(--dl-ls, 1));color:var(--dl-txt2);text-transform:var(--dl-case, uppercase);display:block}
.dst b{font-size:var(--fs-val);letter-spacing:1px;font-weight:600}
@media (max-width:700px){.dial{grid-template-columns:minmax(0,1fr);gap:12px}.gauge{max-width:300px}.reads{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.rd{gap:8px}.rd b{font-size:calc(28px * var(--dl-scale))}.rd span{font-size:max(calc(14px * var(--dl-scale)), var(--dl-min, 0px))}}

