  + "<div class='tp'><div class='in'><div class='lb'>Inside</div><div class='hero'>" + whole(cur) + "</div><div class='st" + (guard ? ' g' : '') + "'>" + status + "</div><div class='hu'>" + hm(hum) + "</div></div>"
  + "<div class='out col'><div class='sp'></div><div class='lb'>Outside</div><div class='big'>" + whole(ot) + "</div><div class='sp'>" + hm(oh) + "</div></div>"
  + "<div class='tg col'>" + arrow('up', 'Raise the target', 'M6 15l6-6 6 6') + "<div class='lb'>Target</div>" + big + arrow('down', 'Lower the target', 'M6 9l6 6 6-6') + "</div></div>"
  + "<div class='ms' role='group' aria-label='Mode' style='--n:" + modes.length + "'>" + modeRow + "</div>"
  + ((reason || start) ? "<div class='hr'>" + reason + start + "</div>" : '')
  + fan + "</div></div>";
]]]

